  "py": "\"\"\"Use case 2 (Hard): what each Overlap Policy does when a run is still going as the next one is due.\"\"\"\nfrom datetime import timedelta\n\nfrom temporalio import workflow\nfrom temporalio.client import Client, Schedule, ScheduleActionStartWorkflow, SchedulePolicy, ScheduleOverlapPolicy, ScheduleSpec\n\nTASK_QUEUE = \"overlap\"\n\n\n@workflow.defn\nclass SlowJob:\n    @workflow.run\n    async def run(self, seconds: float) -> str:\n        await workflow.sleep(timedelta(seconds=seconds))  # cancellable: a cancel request surfaces here\n        return \"done\"\n\n\nasync def create(client: Client, schedule_id: str, policy: ScheduleOverlapPolicy, seconds: float = 4) -> None:\n    await client.create_schedule(schedule_id, Schedule(\n        action=ScheduleActionStartWorkflow(SlowJob.run, seconds, id=\"job-\" + schedule_id, task_queue=TASK_QUEUE),\n        spec=ScheduleSpec(),  # no times: this demo fires the Schedule by hand with trigger() so the timing is exact\n        policy=SchedulePolicy(overlap=policy),\n    ))",
  "ts": "// ===== overlap.ts =====\n/* Use case 2 (Hard): what each Overlap Policy does when a run is still going as the next one is due. */\nimport { sleep } from '@temporalio/workflow';\n\nexport async function slowJob(seconds: number): Promise<string> {\n  await sleep(seconds * 1000); // cancellable: a cancel request surfaces here\n  return 'done';\n}\n\n// ===== overlap.schedule.ts =====\nimport { Client, ScheduleOverlapPolicy } from '@temporalio/client';\n\nexport const TASK_QUEUE = 'overlap';\n\nexport async function create(client: Client, scheduleId: string, overlap: ScheduleOverlapPolicy, seconds = 4) {\n  return client.schedule.create({\n    scheduleId,\n    action: { type: 'startWorkflow', workflowType: 'slowJob', args: [seconds], taskQueue: TASK_QUEUE, workflowId: 'job-' + scheduleId },\n    spec: {}, // no times: this demo fires the Schedule by hand with trigger() so the timing is exact\n    policies: { overlap },\n  });\n}"
